"""从文件读回文本。

读取侧与写入侧使用同一套编码策略：默认固定为 UTF-8，
不随平台的 ANSI 代码页变化，因此同一份文件在 Windows 与 Linux 上
都能解出相同的内容。
"""

from .codec import encoding_for


def read_text(path, encoding="default"):
    """读回整个文件。

    默认按 UTF-8 解码；用 ``utf-8-bom`` / ``utf-8-sig`` 读取时会剥离
    开头的 BOM，用 ``utf-8`` 读取带 BOM 的文件时保留开头的 U+FEFF。
    """
    with open(path, "r", encoding=encoding_for(encoding), newline="") as fh:
        return fh.read()


def read_lines(path, encoding="default"):
    """读回文件并按行切分（不含行尾）。"""
    return read_text(path, encoding=encoding).splitlines()


def detect_bom(path):
    """返回文件开头的字节序标记名称；没有时返回 ``None``。"""
    with open(path, "rb") as fh:
        head = fh.read(4)
    if head.startswith(b"\xef\xbb\xbf"):
        return "utf-8"
    if head.startswith(b"\xff\xfe\x00\x00"):
        return "utf-32-le"
    if head.startswith(b"\x00\x00\xfe\xff"):
        return "utf-32-be"
    if head.startswith(b"\xff\xfe"):
        return "utf-16-le"
    if head.startswith(b"\xfe\xff"):
        return "utf-16-be"
    return None
